CREATE TABLE `ant_cryptotradingbot`.`daily_profit_report` (
  `s_no` BIGINT AUTO_INCREMENT NOT NULL,
  `date` DATE NOT NULL,
  `username` NVARCHAR(50) NOT NULL,
  `start_amount` DECIMAL(12,4) NOT NULL,
  `end_amount` DECIMAL(12,4) NULL,
  `profit_amount` DECIMAL(12,2) NULL,
  `profit_percent` DECIMAL(12,2) NULL,
  `update_date` DATETIME NULL,
  PRIMARY KEY (`s_no`));
