CREATE TABLE `ant_cryptotradingbot`.`bnb_report` (
  `s_no` BIGINT AUTO_INCREMENT NOT NULL,
  `symbol_name` NVARCHAR(50) NOT NULL,
  `order_quantity` DECIMAL(8,3) NOT NULL,
  `buy_price` DECIMAL(12,8) NOT NULL,
  `buy_amount` DECIMAL(12,4) NOT NULL,
  `username` NVARCHAR(50) NOT NULL,
  `order_date` DATETIME NOT NULL,
  PRIMARY KEY (`s_no`));

CREATE TABLE `ant_cryptotradingbot`.`crypto_symbols_name`(
	`symbol_seq_id` bigint AUTO_INCREMENT NOT NULL,
	`symbol_name` NVARCHAR(20) NOT NULL,
	`symbol_full_name` NVARCHAR(100) NOT NULL,
PRIMARY KEY (`symbol_seq_id` ASC));

CREATE TABLE `ant_cryptotradingbot`.`crypto_symbols_data`(
	`symbol_id` BIGINT AUTO_INCREMENT NOT NULL,
	`symbol_name` NVARCHAR(20) NULL,
	`current_askPrice` DECIMAL(10, 8) NULL,
	`current_bidPrice` DECIMAL(10, 8) NULL,
	`24hrs_change` DECIMAL(5, 2) NULL,
	`24hrs_price_change` DECIMAL(10, 8) NULL,
	`upper_BBand_price` DECIMAL(10, 8) NULL,
	`middle_BBand_price` DECIMAL(10, 8) NULL,
	`lower_BBand_price` DECIMAL(10, 8) NULL,
	`MACD_dif` DECIMAL(10, 8) NULL,
	`MACD_dem` DECIMAL(10, 8) NULL,
	`MACD_macd` DECIMAL(10, 8) NULL,
	`last_RSI` DECIMAL(5, 2) NULL,
	`15mins_ST` BIT NOT NULL,
	`30mins_ST` BIT NOT NULL,
	`2hrs_ST` BIT NOT NULL,
	`1d_ST` BIT NOT NULL,
    `Volumes` BIGINT NULL,
	`last_update_DateTime` DATETIME NOT NULL,
	`is_MACD_Trade` BIT NOT NULL,
	`is_ST_Trade` BIT NOT NULL,
