	`signal_type` NVARCHAR(100) NULL,
	`order_quantity` DECIMAL(8, 2) NULL,
	`buy_price` DECIMAL(12, 8) NULL,
	`current_price` DECIMAL(12, 8) NULL,
	`profit_percent` DECIMAL(8, 2) NULL,
	`target_price` DECIMAL(12, 8) NULL,
