(
	`s_no` ASC
));
ALTER TABLE `ant_cryptotradingbot`.`order_report` ADD `commission_price` DECIMAL(12, 8) NULL;
#DROP TABLE `ant_cryptotradingbot`.`db_query_data`;
CREATE TABLE `ant_cryptotradingbot`.`db_query_data`(
	`track_id` BIGINT auto_increment NOT NULL,
	`track_date` DATETIME NOT NULL,
	`symbol_name` NVARCHAR(20) NOT NULL,
	`signal_type` NVARCHAR(100) NOT NULL,
	`current_askPrice` DECIMAL(10, 8) NULL,
	`upper_BBand_price` DECIMAL(10, 8) NULL,
	`middle_BBand_price` DECIMAL(10, 8) NULL,
	`lower_BBand_price` DECIMAL(10, 8) NULL,
	`MACD_dif` DECIMAL(10, 8) NULL,
	`MACD_dem` DECIMAL(10, 8) NULL,
	`MACD_macd` DECIMAL(10, 8) NULL,
	`last_RSI` DECIMAL(5, 2) NULL,
	`15mins_ST` BIT NOT NULL Default 0,
	`30mins_ST` BIT NOT NULL Default 0,
	`2hrs_ST` BIT NOT NULL Default 0,
	`1d_ST` BIT NOT NULL Default 0,
	`Update_Date` DATETIME NULL,
 PRIMARY KEY (`track_id` ASC));

#DROP TABLE `ant_cryptotradingbot`.`CS_Patterns`;
CREATE TABLE `ant_cryptotradingbot`.`CS_Patterns` (
	`s_no` INT AUTO_INCREMENT NOT NULL,
	`PatternName` NVARCHAR(200) NOT NULL,
	`KeyWord` NVARCHAR(50) NOT NULL,
	`SignalType` NVARCHAR(50) NULL,
	`is_Active` BIT NOT NULL,
PRIMARY KEY (`s_no`));

-- DROP TABLE `ant_cryptotradingbot`.`live_patterns_signal`;
CREATE TABLE `ant_cryptotradingbot`.`live_patterns_signal` (
	`symbol_name` NVARCHAR(50) NOT NULL,
	`PatternName` NVARCHAR(200) NOT NULL,
	`SignalType` NVARCHAR(50) NOT NULL,
	`Update_Date` DATETIME NOT NULL
	);

-- DROP TABLE `ant_cryptotradingbot`.`symbol_support_resistance`;
CREATE TABLE `ant_cryptotradingbot`.`symbol_support_resistance` (
	`symbol_name` NVARCHAR(50) NOT NULL,
	`Date` DATETIME NOT NULL,
	`Type` NVARCHAR(50) NOT NULL,
	`Value` DECIMAL(12, 8) NOT NULL
	);

CREATE TABLE `ant_cryptotradingbot`.`ant_user_wallet`(
	`wallet_seq_id` BIGINT AUTO_INCREMENT NOT NULL,
	`username` NVARCHAR(50) NOT NULL,
	`initial_investment` DECIMAL(12, 2) NOT NULL default 0,
	`binance_exchange_usdt` DECIMAL(12, 2) NOT NULL default 0,
	`ant_wallet_balance` DECIMAL(12, 2) NOT NULL default 0,
	`total_deposit` DECIMAL(12, 2) NOT NULL default 0,
	`total_withdrawal` DECIMAL(12, 2) NOT NULL default 0,
	`referal_income` DECIMAL(12, 2) NOT NULL default 0,
	`activation_balance` DECIMAL(12, 2) NOT NULL default 0,
	`withdrawal_eligible` DECIMAL(12, 2) NOT NULL default 0,
 PRIMARY KEY (`wallet_seq_id` ASC));

#DROP TABLE `ant_cryptotradingbot`.`ant_user_data`;
CREATE TABLE `ant_cryptotradingbot`.`ant_user_data`(
	`user_id` BIGINT AUTO_INCREMENT NOT NULL,
	`full_name` NVARCHAR(100) NOT NULL,
	`username` NVARCHAR(50) NOT NULL,
	`password` NVARCHAR(50) NOT NULL,
	`email_id` NVARCHAR(100) NOT NULL,
	`role` NVARCHAR(50) NOT NULL Default 'User',
	`exchange_name` NVARCHAR(50) NULL,
	`api_key` NVARCHAR(100) NULL,
	`api_secret` NVARCHAR(100) NULL,
	`max_invest` INT NOT NULL Default 0,
	`validity` DATETIME NULL,
