UPDATE `ant_cryptotradingbot`.`CS_Patterns` SET `is_Active` = true,`SignalType`='bullish'  where `PatternName` in ('Inverted Hammer','Hammer','Piercing Pattern','Morning Star','Morning Doji Star','Three Advancing White Soldiers');
UPDATE `ant_cryptotradingbot`.`CS_Patterns` SET `is_Active` = true,`SignalType`='bearish' where `PatternName` in ('Hanging Man','Shooting Star','Evening Star','Evening Doji Star','Three Black Crows','Dark Cloud Cover');
UPDATE `ant_cryptotradingbot`.`CS_Patterns` SET `is_Active` = true,`SignalType`='both' where `PatternName` in ('Engulfing Pattern');

