ALTER TABLE `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` ALTER `last_update_DateTime` SET DEFAULT (current_timestamp());
ALTER TABLE `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` ALTER `is_Active` SET DEFAULT (1);

ALTER TABLE `ant_cryptotradingbot`.`CS_Patterns` ALTER `is_Active` SET DEFAULT (0);
