ALTER TABLE `ant_cryptotradingbot`.`ant_user_data` ALTER `referal_by` SET DEFAULT ('admin_ant#1');
-- sp
CREATE DEFINER=`root`@`localhost` PROCEDURE `user_recent_activity`(
username NVARCHAR(50),
fromDate NVARCHAR(50),
toDate NVARCHAR(50)
)
BEGIN
select cast(`Date` as Date) as 'date', side, activity, `type`, quantity, symbol, amount from (
select bcsd.order_date as 'Date', 'Buy' as side, concat('Bought ', replace(bcsn.symbol_full_name, '_', '')) as activity, bcsd.signal_type as 'type', FLOOR(bcsd.order_quantity) as quantity, bcsn.symbol_name as symbol, concat(bcsd.buy_amount, ' USDT') as amount from `ant_cryptotradingbot`.`order_report`  as bcsd
inner join `ant_cryptotradingbot`.`crypto_symbols_name` as bcsn on bcsn.symbol_name = replace(bcsd.symbol_name, 'USDT', '')
where bcsd.username = username and bcsd.order_date >= fromDate and bcsd.order_date <= toDate
union all
select csd.update_date as 'Date', 'Sell' as side, concat('Sell ', replace(csn.symbol_full_name, '_', '')) as activity, csd.sell_reason as 'type', FLOOR(csd.order_quantity) as quantity, csn.symbol_name as symbol, concat(csd.sell_amount, ' USDT') as amount from `ant_cryptotradingbot`.`order_report`  as csd
inner join `ant_cryptotradingbot`.`crypto_symbols_name` as csn on csn.symbol_name = replace(csd.symbol_name, 'USDT', '')
where csd.username = username and csd.order_date >= fromDate and csd.order_date <= toDate
order by `Date` desc) as cte;

END
##-------Buy MACD OLD
SELECT csd.`symbol_name`, `current_askPrice`, `upper_BBand_price`, `middle_BBand_price`, `lower_BBand_price`, `MACD_dif`, `MACD_dem`, `MACD_macd`, `last_RSI`, `2hrs_ST`, csd.`last_update_DateTime` FROM `ant_cryptotradingbot`.`crypto_symbols_data` as csd 
                INNER JOIN `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` as csmsd on csd.symbol_name = csmsd.symbol_name 
                WHERE (csd.upper_BBand_price > csd.current_askPrice 
                and (csd.middle_BBand_price < csd.current_askPrice or ((csd.middle_BBand_price + csd.lower_BBand_price)/2) < csd.current_askPrice)) 
                and csmsd.sum_dem_macd_current >= 0 and csmsd.sum_dem_macd_prv < csmsd.sum_dem_macd_current and csd.MACD_dif > 0 and csd.MACD_dem <= 0 and csd.MACD_macd > 0 and csd.last_RSI < 55 and csd.`2hrs_ST` = True and csd.is_Active = True;
##pattern--
SELECT csd.`symbol_name`, `current_askPrice`, `upper_BBand_price`, `middle_BBand_price`, `lower_BBand_price`, `MACD_dif`, `MACD_dem`, `MACD_macd`, `last_RSI`, `2hrs_ST`, csd.`last_update_DateTime`, lps.`PatternName` FROM `ant_cryptotradingbot`.`crypto_symbols_data` as csd 
                INNER JOIN `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` as csmsd on csd.symbol_name = csmsd.symbol_name 
                INNER JOIN `ant_cryptotradingbot`.`live_patterns_signal` as lps on csd.symbol_name = lps.symbol_name 
                WHERE csd.MACD_macd > 0 and csd.last_RSI < 60 and csd.`2hrs_ST` = True and csd.is_Active = True
                and lps.`PatternName` in ('Inverted Hammer','Hammer','Piercing Pattern','Morning Star','Morning Doji Star','Three Advancing White Soldiers','Engulfing Pattern') and lps.SignalType = 'bullish';

##-------Buy ST OLD
SELECT csd.`symbol_name`, `current_askPrice`, `upper_BBand_price`, `middle_BBand_price`, `lower_BBand_price`, `MACD_dif`, `MACD_dem`, `MACD_macd`, `last_RSI`, `2hrs_ST`, csd.`last_update_DateTime` FROM `ant_cryptotradingbot`.`crypto_symbols_data` as csd 
                INNER JOIN `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` as csmsd on csd.symbol_name = csmsd.symbol_name 
                WHERE (csd.upper_BBand_price > csd.current_askPrice 
                and (csd.middle_BBand_price < csd.current_askPrice or ((csd.middle_BBand_price + csd.lower_BBand_price)/2) < csd.current_askPrice)) 
                and csmsd.`2hrs_ST_prv` = False and csmsd.`2hrs_ST_current` = True and csmsd.sum_dem_macd_prv < csmsd.sum_dem_macd_current and csd.MACD_dif > 0 and csd.MACD_macd > 0 and csd.last_RSI < 60 and csd.last_RSI > 45 and csd.`2hrs_ST` = True and csd.is_Active = True
               ; 
#Pattern----
SELECT csd.`symbol_name`, `current_askPrice`, `upper_BBand_price`, `middle_BBand_price`, `lower_BBand_price`, `MACD_dif`, `MACD_dem`, `MACD_macd`, csmsd.`sum_dem_macd_prv`, csmsd.`sum_dem_macd_current`, `last_RSI`, `2hrs_ST`, csd.`last_update_DateTime`, lps.`PatternName` FROM `ant_cryptotradingbot`.`crypto_symbols_data` as csd 
                        INNER JOIN `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` as csmsd on csd.symbol_name = csmsd.symbol_name
                        INNER JOIN `ant_cryptotradingbot`.`live_patterns_signal` as lps on csd.symbol_name = lps.symbol_name  
                        WHERE ((lps.`PatternName` in ('Hanging Man','Shooting Star','Evening Star','Evening Doji Star','Three Black Crows','Dark Cloud Cover','Engulfing Pattern') and lps.SignalType = 'bearish') and csd.last_RSI > 65 and (csd.`15mins_ST` = False or csd.`2hrs_ST` = False))
--                         and csd.`symbol_name`='{}';
						and csd.`symbol_name` in (SELECT `symbol_name` FROM `ant_cryptotradingbot`.`current_buy_order_report`);

##--------Buy NEW - change
SELECT csd.`symbol_name`, `current_askPrice`, `upper_BBand_price`, `middle_BBand_price`, `lower_BBand_price`, `MACD_dif`, `MACD_dem`, `MACD_macd`, `last_RSI`, `2hrs_ST`, csd.`last_update_DateTime` FROM `ant_cryptotradingbot`.`crypto_symbols_data` as csd 
                INNER JOIN `ant_cryptotradingbot`.`crypto_symbols_macd_st_data` as csmsd on csd.symbol_name = csmsd.symbol_name 
                WHERE (csd.upper_BBand_price > csd.current_askPrice 
                and (csd.middle_BBand_price < csd.current_askPrice or ((csd.middle_BBand_price + csd.lower_BBand_price)/2) < csd.current_askPrice)) 
                and csmsd.sum_dem_macd_prv < csmsd.sum_dem_macd_current 
                and ((((csd.MACD_dem < 0 and csd.MACD_dif < 0) or (csd.MACD_dem < 0 and csd.MACD_dif > 0))
                and csd.MACD_macd > 0 and csd.`15mins_ST` = True) or (csd.last_RSI < 30 and (csd.MACD_dem > 0 and csd.MACD_dif > 0))) and csd.`2hrs_ST` = True and csd.is_Active = True;
                